<script setup>import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import {Head,Link,useForm} from '@inertiajs/vue3'; defineProps({advisory:Object,matches:Array}); const forms={}; const formFor=(match)=>forms[match.id] ||= useForm({status:match.status,notes:match.notes||''}); const save=(match)=>formFor(match).patch(route('advisory-matches.update',match.id),{preserveScroll:true});</script>
<template><Head :title="advisory.external_id"/><AuthenticatedLayout><template #header><div><p class="text-sm font-semibold uppercase text-teal-700">{{advisory.external_id}}</p><h1 class="mt-1 text-xl font-semibold">{{advisory.title}}</h1></div></template><div class="mx-auto max-w-6xl space-y-6 px-4 py-8"><section class="rounded-xl border bg-white p-6 shadow-sm"><div class="flex flex-wrap gap-3 text-xs font-semibold uppercase text-slate-500"><span>{{advisory.severity}} severity</span><span>{{advisory.source.replace('_',' ')}}</span><span v-for="cve in advisory.cve_ids" :key="cve">{{cve}}</span></div><p class="mt-4 text-sm leading-6 text-slate-700">{{advisory.summary||'No summary was provided.'}}</p><div class="mt-5 flex flex-wrap gap-2"><span v-for="product in advisory.affected_vendors_models" :key="product.vendor+product.model" class="rounded-full bg-slate-100 px-3 py-1 text-xs">{{product.vendor}} · {{product.model}}<template v-if="product.versions?.length"> · {{product.versions.join(', ')}}</template></span></div></section><section class="rounded-xl border bg-white p-6 shadow-sm"><h2 class="text-lg font-semibold">Affected assets in your organization</h2><div class="mt-4 space-y-4"><form v-for="match in matches" :key="match.id" @submit.prevent="save(match)" class="grid gap-3 rounded-lg border p-4 lg:grid-cols-[1fr_190px_2fr_auto]"><div><Link :href="route('assets.show',match.asset.id)" class="font-semibold text-teal-800">{{match.asset.name}}</Link><p class="text-xs text-slate-500">{{match.asset.site.name}} · matched on {{match.matched_on}}</p></div><select v-model="formFor(match).status" class="rounded-lg border-slate-300 text-sm"><option v-for="status in ['open','acknowledged','patched','compensating_control','false_positive']" :value="status" :key="status">{{status.replace('_',' ')}}</option></select><input v-model="formFor(match).notes" :required="['compensating_control','false_positive'].includes(formFor(match).status)" placeholder="Notes (required for control or false positive)" class="rounded-lg border-slate-300 text-sm"/><button class="rounded-lg border px-4 py-2 text-sm font-medium">Save</button></form><p v-if="!matches.length" class="py-8 text-center text-sm text-slate-500">No assets currently match this advisory.</p></div></section></div></AuthenticatedLayout></template>
